import{_ as s,o as t,c as r,ah as i}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Élèves et tuteurs","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/eleves-tuteurs.md","filePath":"src/guide/admin/eleves-tuteurs.md"}'),l={name:"guide/admin/eleves-tuteurs.md"};function a(n,e,o,u,c,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="eleves-et-tuteurs" tabindex="-1">Élèves et tuteurs <a class="header-anchor" href="#eleves-et-tuteurs" aria-label="Permalink to &quot;Élèves et tuteurs&quot;">​</a></h1><p>Cette section couvre le dossier d&#39;un élève et tout ce qui s&#39;y rattache : son inscription en classe, ses tuteurs (parents), son éventuel accès personnel au portail élève, et ses matières de spécialité.</p><h2 id="dossiers-eleves" tabindex="-1">Dossiers élèves <a class="header-anchor" href="#dossiers-eleves" aria-label="Permalink to &quot;Dossiers élèves&quot;">​</a></h2><p><strong>Structure scolaire → Élèves</strong> liste les élèves de l&#39;instance, avec une recherche par nom et un filtre par classe (y compris « Non affecté » pour les élèves sans classe sur l&#39;année en cours).</p><p>Pour créer un élève :</p><ol><li>Cliquez sur <strong>Nouvel élève</strong>.</li><li>Renseignez le <strong>Prénom</strong>, le <strong>Nom de famille</strong>, la <strong>Date de naissance</strong> (facultative).</li><li>Choisissez une <strong>Classe</strong> pour l&#39;année scolaire en cours, ou laissez « Non affecté » pour créer le dossier sans inscription immédiate.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>En modifiant un élève, vous retrouvez les mêmes champs, ainsi que deux tableaux en lecture seule si l&#39;élève a de l&#39;historique :</p><ul><li><strong>Historique des inscriptions</strong> — les classes suivies sur les années scolaires précédentes.</li><li><strong>Historique de référentiel</strong> — les changements de référentiel pédagogique (français ↔ togolais) subis par l&#39;élève, avec la date et l&#39;auteur du changement.</li></ul><p>Depuis la fiche d&#39;un élève, trois boutons ouvrent des écrans dédiés : <strong>Matières de spécialité</strong>, <strong>Tuteurs</strong> et <strong>Compte élève</strong> (détaillés ci-dessous).</p><h2 id="tuteurs-parents" tabindex="-1">Tuteurs (parents) <a class="header-anchor" href="#tuteurs-parents" aria-label="Permalink to &quot;Tuteurs (parents)&quot;">​</a></h2><p>Depuis la fiche d&#39;un élève, cliquez sur <strong>Tuteurs</strong> pour gérer les personnes qui ont accès au portail parent pour cet élève.</p><p>Pour ajouter un tuteur :</p><ol><li>Cliquez sur <strong>Ajouter un tuteur</strong>.</li><li>Renseignez le <strong>Nom</strong>, l&#39;<strong>E-mail</strong>, le <strong>Lien de parenté</strong> (Père, Mère, Tuteur légal ou Autre), et cochez <strong>Contact principal</strong> si c&#39;est le contact de référence.</li><li>Répétez pour chaque tuteur supplémentaire (bouton <strong>Retirer</strong> pour en supprimer un du formulaire).</li><li>Cliquez sur <strong>Enregistrer les modifications</strong>.</li></ol><p>Chaque tuteur ainsi rattaché a accès au portail parent pour cet élève et pour tous les autres élèves auxquels il est rattaché par ailleurs.</p><h2 id="compte-eleve-portail-eleve" tabindex="-1">Compte élève (portail élève) <a class="header-anchor" href="#compte-eleve-portail-eleve" aria-label="Permalink to &quot;Compte élève (portail élève)&quot;">​</a></h2><p>Depuis la fiche d&#39;un élève, cliquez sur <strong>Compte élève</strong>. Un accès personnel au portail élève n&#39;est possible que pour un élève inscrit au lycée ou au-delà — pour les autres, la page affiche un message d&#39;inéligibilité et rien d&#39;autre.</p><p>Pour un élève éligible :</p><ul><li><strong>Créer le compte</strong> — renseignez une adresse e-mail, cliquez sur <strong>Créer le compte</strong> ; l&#39;élève peut alors se connecter avec cette adresse.</li><li><strong>Mettre à jour l&#39;e-mail</strong> — si un compte existe déjà, changez l&#39;adresse et cliquez sur <strong>Mettre à jour l&#39;e-mail</strong>.</li><li><strong>Révoquer l&#39;accès</strong> — supprime l&#39;accès personnel de l&#39;élève sans toucher à son dossier.</li></ul><h2 id="matieres-de-specialite" tabindex="-1">Matières de spécialité <a class="header-anchor" href="#matieres-de-specialite" aria-label="Permalink to &quot;Matières de spécialité&quot;">​</a></h2><p>Depuis la fiche d&#39;un élève, cliquez sur <strong>Matières de spécialité</strong>. Cet écran n&#39;affiche quelque chose que si l&#39;élève a une inscription active et que son département a des matières marquées « de spécialité » (voir <a href="/era-guide/guide/admin/structure-etablissement.html">Structure de l&#39;établissement</a>).</p><p>Pour chaque matière de spécialité proposée :</p><ol><li>Cochez la case pour la sélectionner pour cet élève.</li><li>Renseignez, si besoin, un <strong>coefficient</strong> personnalisé qui remplace celui défini par défaut au niveau du département — sinon le coefficient par défaut du département s&#39;applique.</li><li>Cliquez sur <strong>Enregistrer les modifications</strong>.</li></ol>',22)])])}const m=s(l,[["render",a]]);export{g as __pageData,m as default};
